export interface Activity {
  id: string;
  name: string;
  description?: string;
  category: string;
  dailyTarget?: number;
  createdAt: string;
  updatedAt?: string;
}

export interface DailyStatus {
  activityId: string;
  date: string; // YYYY-MM-DD
  completed: boolean;
  value?: number; // aktueller Wert für Ziele
  completedAt?: string; // ISO timestamp when completed
}

export interface AppState {
  activities: Activity[];
  dailyStatuses: DailyStatus[];
  currentViewDate: string; // YYYY-MM-DD
}

export interface VersionedData {
  version: number;
  data: AppState;
}

export const VERSIONED_DATA_VERSION = 1;

// Storage keys
export const STORAGE_KEY = 'pulseboard_data_v1';
export const THEME_STORAGE_KEY = 'pulseboard_theme';

// Storage helpers
export interface StorageError {
  type: 'corrupted' | 'invalid_version' | 'parse_error';
  message: string;
}

export type Theme = 'light' | 'dark';

import { 
  AppState, 
  VersionedData, 
  STORAGE_KEY, 
  VERSIONED_DATA_VERSION,
  StorageError
} from '@/types';

/**
 * Initialisiert die Datenstruktur mit Standardwerten
 */
export function getInitialAppState(): AppState {
  return {
    activities: [],
    dailyStatuses: [],
    currentViewDate: new Date().toISOString().split('T')[0]
  };
}

/**
 * Validiert die Version der gespeicherten Daten
 */
export function validateVersion(data: unknown): data is VersionedData {
  if (typeof data !== 'object' || data === null) return false;

  const versionedData = data as VersionedData;

  if (typeof versionedData.version !== 'number') return false;
  if (typeof versionedData.data !== 'object' || versionedData.data === null) return false;

  const appState = versionedData.data as AppState;

  if (!Array.isArray(appState.activities)) return false;
  if (!Array.isArray(appState.dailyStatuses)) return false;
  if (typeof appState.currentViewDate !== 'string') return false;

  // Validate activity structures
  for (const activity of appState.activities) {
    if (typeof activity.id !== 'string') return false;
    if (typeof activity.name !== 'string') return false;
    if (typeof activity.category !== 'string') return false;
    if (typeof activity.createdAt !== 'string') return false;

    if (activity.description !== undefined && typeof activity.description !== 'string') return false;
    if (activity.dailyTarget !== undefined && typeof activity.dailyTarget !== 'number') return false;
    if (activity.updatedAt !== undefined && typeof activity.updatedAt !== 'string') return false;
  }

  // Validate daily status structures
  for (const status of appState.dailyStatuses) {
    if (typeof status.activityId !== 'string') return false;
    if (typeof status.date !== 'string') return false;
    if (typeof status.completed !== 'boolean') return false;

    if (status.value !== undefined && typeof status.value !== 'number') return false;
    if (status.completedAt !== undefined && typeof status.completedAt !== 'string') return false;
  }

  // Validate date format YYYY-MM-DD
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!dateRegex.test(appState.currentViewDate)) return false;

  return true;
}

/**
 * Lädt die gespeicherten Daten mit Validierung und Fehlerbehandlung
 */
export function loadAppState(): AppState {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);

    if (!stored) {
      return getInitialAppState();
    }

    let parsed: unknown;
    try {
      parsed = JSON.parse(stored);
    } catch (e) {
      console.error('Failed to parse stored data:', e);
      // Daten beschädigt - zurücksetzen
      return getInitialAppState();
    }

    if (!validateVersion(parsed)) {
      console.error('Invalid data structure or version');
      return getInitialAppState();
    }

    // Version kompatibel? Wenn nicht, migrieren
    if (parsed.version !== VERSIONED_DATA_VERSION) {
      console.warn(`Data version mismatch: ${parsed.version} vs ${VERSIONED_DATA_VERSION}`);
      return getInitialAppState(); // In Produktionscode würde man Migration hier einbauen
    }

    return parsed.data;
  } catch (error) {
    console.error('Error loading app state:', error);
    return getInitialAppState();
  }
}

/**
 * Speichert den aktuellen AppState
 */
export function saveAppState(appState: AppState): void {
  try {
    const data: VersionedData = {
      version: VERSIONED_DATA_VERSION,
      data: appState
    };

    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch (error) {
    console.error('Error saving app state:', error);
    throw new Error(`Failed to save data: ${error instanceof Error ? error.message : String(error)}`);
  }
}

/**
 * Löscht alle gespeicherten Daten
 */
export function clearStorage(): void {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch (error) {
    console.error('Error clearing storage:', error);
  }
}

/**
 * Iteriert über alle Tage in einem Bereich
 */
export function getDaysInRange(startDate: Date, endDate: Date): string[] {
  const days: string[] = [];
  const current = new Date(startDate);

  while (current <= endDate) {
    days.push(current.toISOString().split('T')[0]);
    current.setDate(current.getDate() + 1);
  }

  return days;
}

/**
 * Formatierter Tagename für die UI
 */
export function formatDisplayDate(dateStr: string): string {
  if (!dateStr) return '';

  try {
    const date = new Date(dateStr + 'T00:00:00');
    return new Intl.DateTimeFormat('de-DE', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    }).format(date);
  } catch (e) {
    return dateStr;
  }
}

/**
 * Prüft, ob ein Tag in der Zukunft liegt
 */
export function isFutureDate(dateStr: string): boolean {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const date = new Date(dateStr + 'T00:00:00');
  return date > today;
}

/**
 * Prüft, ob ein Tag in der Vergangenheit liegt
 */
export function isPastDate(dateStr: string): boolean {
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const date = new Date(dateStr + 'T00:00:00');
  return date < today;
}

/**
 * Erstellt eine UUID v4
 */
export function generateUUID(): string {
  // Verwendet.crypto wenn verfügbar, sonst Fallback
  if (typeof window !== 'undefined' && window.crypto) {
    const array = new Uint8Array(16);
    window.crypto.getRandomValues(array);

    // Setze Version (4) und Variantenbits
    array[6] = (array[6] & 0x0f) | 0x40; // Version 4
    array[8] = (array[8] & 0x3f) | 0x80; // Variantenbits

    // Konvertiere zu hex string
    const byteToHex: string[] = [];
    for (let i = 0; i < 256; ++i) {
      byteToHex[i] = (i + 0x100).toString(16).slice(1);
    }

    let offset = 0;
    const bth = byteToHex;
    return [
      bth[array[offset++]], bth[array[offset++]], bth[array[offset++]], bth[array[offset++]],
      '-', bth[array[offset++]], bth[array[offset++]],
      '-', bth[array[offset++]], bth[array[offset++]],
      '-', bth[array[offset++]], bth[array[offset++]],
      '-', bth[array[offset++]], bth[array[offset++]], bth[array[offset++]], bth[array[offset++]],
      bth[array[offset++]], bth[array[offset++]], bth[array[offset++]], bth[array[offset++]],
      bth[array[offset++]], bth[array[offset++]], bth[array[offset++]], bth[array[offset++]],
      bth[array[offset++]], bth[array[offset++]], bth[array[offset++]], bth[array[offset++]]
    ].join('');
  }

  // Fallback ohne crypto
  const template = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx';
  const uuid = template.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });

  return uuid;
}

import { useState, useEffect, useCallback } from 'react';
import { AppState, StorageError } from '@/types';
import { loadAppState, saveAppState, getInitialAppState } from '@/utils/storage';

/**
 * Hook für state management mit persistence
 */
export function useStorageState(initialValue?: AppState): [AppState, (state: Partial<AppState>) => void] {
  const [appState, setAppState] = useState<AppState>(() => {
    if (initialValue) {
      return initialValue;
    }

    try {
      return loadAppState();
    } catch (error) {
      console.error('Error loading initial state:', error);
      return getInitialAppState();
    }
  });

  const updateState = useCallback((partial: Partial<AppState>) => {
    setAppState(prev => {
      const newState = { ...prev, ...partial };
      try {
        saveAppState(newState);
      } catch (error) {
        console.error('Error saving state:', error);
      }
      return newState;
    });
  }, []);

  // Sync bei Änderungen
  useEffect(() => {
    try {
      saveAppState(appState);
    } catch (error) {
      console.error('Error initializing storage:', error);
    }
  }, [appState]);

  return [appState, updateState];
}

/**
 * Hook für eine einzelne Aktivität mit persistence
 */
export function useStorageActivity(activityId: string | null): [any, (updates: Partial<any>) => void] {
  const [appState, updateAppState] = useStorageState();

  const activity = appState.activities.find(a => a.id === activityId);

  const updateActivity = useCallback((updates: Partial<any>) => {
    if (!activityId) return;

    updateAppState({
      activities: appState.activities.map(a => {
        if (a.id === activityId) {
          return { ...a, ...updates };
        }
        return a;
      })
    });
  }, [activityId, appState.activities, updateAppState]);

  return [activity, updateActivity];
}

import { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { AppState, Activity, DailyStatus, Theme } from '@/types';
import { useStorageState } from '@/hooks/useStorageState';
import { generateUUID } from '@/utils/uuid';

interface AppContextType {
  // State
  appState: AppState;

  // Actions
  addActivity: (activity: Omit<Activity, 'id' | 'createdAt' | 'updatedAt'>) => void;
  updateActivity: (id: string, updates: Partial<Activity>) => void;
  deleteActivity: (id: string) => void;

  toggleActivityStatus: (activityId: string, date: string) => void;
  setActivityValue: (activityId: string, date: string, value: number) => void;

  changeDate: (newDate: string) => void;
  goToday: () => void;

  theme: Theme;
  toggleTheme: () => void;

  // Helpers
  getCompletedCount: (date?: string) => number;
  getTotalCount: () => number;
  getProgressPercent: (date?: string) => number;
  getCategoryStats: (date?: string) => Record<string, { completed: number; total: number }>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export function AppProvider({ children }: { children: ReactNode }) {
  const [appState, updateAppState] = useStorageState();
  const [theme, setTheme] = useState<Theme>(() => {
    try {
      const savedTheme = localStorage.getItem('pulseboard_theme') as Theme;
      return savedTheme || 'light';
    } catch {
      return 'light';
    }
  });

  // Theme persistence
  useEffect(() => {
    localStorage.setItem('pulseboard_theme', theme);

    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  // Theme Toggle
  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  // Aktivität hinzufügen
  const addActivity = (activity: Omit<Activity, 'id' | 'createdAt' | 'updatedAt'>) => {
    const newActivity: Activity = {
      ...activity,
      id: generateUUID(),
      createdAt: new Date().toISOString()
    };

    updateAppState({
      activities: [...appState.activities, newActivity]
    });
  };

  // Aktivität aktualisieren
  const updateActivity = (id: string, updates: Partial<Activity>) => {
    updateAppState({
      activities: appState.activities.map(a => 
        a.id === id ? { ...a, ...updates, updatedAt: new Date().toISOString() } : a
      )
    });
  };

  // Aktivität löschen
  const deleteActivity = (id: string) => {
    updateAppState({
      activities: appState.activities.filter(a => a.id !== id),
      dailyStatuses: appState.dailyStatuses.filter(s => s.activityId !== id)
    });
  };

  // Status einer Aktivität an einem Tag umschalten
  const toggleActivityStatus = (activityId: string, date: string) => {
    const existingIndex = appState.dailyStatuses.findIndex(
      s => s.activityId === activityId && s.date === date
    );

    if (existingIndex >= 0) {
      // Umkehren
      const newStatus = !appState.dailyStatuses[existingIndex].completed;

      updateAppState({
        dailyStatuses: appState.dailyStatuses.map((s, i) => {
          if (i === existingIndex) {
            return {
              ...s,
              completed: newStatus,
              completedAt: newStatus ? new Date().toISOString() : undefined
            };
          }
          return s;
        })
      });
    } else {
      // Hinzufügen
      const newStatus: DailyStatus = {
        activityId,
        date,
        completed: true,
        value: 0,
        completedAt: new Date().toISOString()
      };

      updateAppState({
        dailyStatuses: [...appState.dailyStatuses, newStatus]
      });
    }
  };

  // Wert einer Aktivität an einem Tag setzen
  const setActivityValue = (activityId: string, date: string, value: number) => {
    const existingIndex = appState.dailyStatuses.findIndex(
      s => s.activityId === activityId && s.date === date
    );

    if (existingIndex >= 0) {
      updateAppState({
        dailyStatuses: appState.dailyStatuses.map((s, i) => {
          if (i === existingIndex) {
            return { ...s, value };
          }
          return s;
        })
      });
    } else {
      updateAppState({
        dailyStatuses: [
          ...appState.dailyStatuses,
          { activityId, date, completed: value > 0, value }
        ]
      });
    }
  };

  // Datum ändern
  const changeDate = (newDate: string) => {
    updateAppState({ currentViewDate: newDate });
  };

  // Zu heute springen
  const goToday = () => {
    updateAppState({ currentViewDate: new Date().toISOString().split('T')[0] });
  };

  // Hilfsfunktionen
  const getCompletedCount = (date: string = appState.currentViewDate) => {
    return appState.dailyStatuses.filter(
      s => s.date === date && s.completed
    ).length;
  };

  const getTotalCount = () => {
    return appState.activities.length;
  };

  const getProgressPercent = (date: string = appState.currentViewDate) => {
    const totalCount = getTotalCount();

    if (totalCount === 0) return 0;

    const completedCount = getCompletedCount(date);

    return Math.round((completedCount / totalCount) * 100);
  };

  const getCategoryStats = (date: string = appState.currentViewDate) => {
    const stats: Record<string, { completed: number; total: number }> = {};

    appState.activities.forEach(activity => {
      const cat = activity.category || 'Ohne Kategorie';

      if (!stats[cat]) {
        stats[cat] = { completed: 0, total: 0 };
      }

      stats[cat].total++;

      // Prüfen ob für das Datum abgehakt
      const status = appState.dailyStatuses.find(
        s => s.activityId === activity.id && s.date === date
      );

      if (status?.completed) {
        stats[cat].completed++;
      }
    });

    return stats;
  };

  const value: AppContextType = {
    appState,
    addActivity,
    updateActivity,
    deleteActivity,
    toggleActivityStatus,
    setActivityValue,
    changeDate,
    goToday,
    theme,
    toggleTheme,
    getCompletedCount,
    getTotalCount,
    getProgressPercent,
    getCategoryStats
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
}

export function useApp() {
  const context = useContext(AppContext);

  if (!context) {
    throw new Error('useApp must be used within an AppProvider');
  }

  return context;
}

import { ReactNode } from 'react';
import ReactDOM from 'react-dom';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  children: ReactNode;
}

export function Modal({ isOpen, onClose, title, children }: ModalProps) {
  if (!isOpen) return null;

  const handleOverlayClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) {
      onClose();
    }
  };

  return ReactDOM.createPortal(
    <div 
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4"
      onClick={handleOverlayClick}
    >
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl max-w-md w-full overflow-hidden animate-in fade-in zoom-in duration-200">
        {title && (
          <div className="px-6 py-4 border-b border-gray-200 dark:border-slate-700">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">{title}</h3>
          </div>
        )}

        <div className="p-6">
          {children}
        </div>
      </div>
    </div>,
    document.body
  );
}

import { ReactNode } from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
  icon?: ReactNode;
}

export function Button({ 
  children, 
  variant = 'primary', 
  size = 'md',
  isLoading,
  icon,
  className = '',
  disabled,
  ...props
}: ButtonProps) {
  const baseClasses = 'inline-flex items-center justify-center font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg';

  const variants = {
    primary: 'bg-blue-600 hover:bg-blue-700 text-white focus:ring-blue-500',
    secondary: 'bg-gray-100 hover:bg-gray-200 text-gray-900 dark:bg-slate-700 dark:hover:bg-slate-600 dark:text-white focus:ring-gray-500',
    danger: 'bg-red-600 hover:bg-red-700 text-white focus:ring-red-500',
    ghost: 'hover:bg-gray-100 dark:hover:bg-slate-800 text-gray-700 dark:text-gray-300'
  };

  const sizes = {
    sm: 'px-3 py-1.5 text-sm',
    md: 'px-4 py-2 text-base',
    lg: 'px-6 py-3 text-lg'
  };

  return (
    <button
      className={`${baseClasses} ${variants[variant]} ${sizes[size]} ${className}`}
      disabled={disabled || isLoading}
      {...props}
    >
      {isLoading ? (
        <svg className="animate-spin -ml-1 mr-2 h-4 w-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
      ) : icon ? (
        <span className="mr-1.5">{icon}</span>
      ) : null}

      {children}
    </button>
  );
}

