import { describe, it, expect, beforeEach } from 'vitest';
import { renderHook, cleanup } from '@testing-library/react';
import { useStorageState } from '../useStorageState';

describe('useStorageState', () => {
  beforeEach(() => {
    cleanup();
    localStorage.clear();
  });

  it('should return initial state when no data exists', () => {
    const { result } = renderHook(() => useStorageState());

    expect(result.current[0]).toBeDefined();
    expect(result.current[0].activities).toEqual([]);
    expect(result.current[0].dailyStatuses).toEqual([]);
  });

  it('should allow updating state', () => {
    const { result } = renderHook(() => useStorageState());

    // Initial state
    expect(result.current[0].activities).toEqual([]);

    // Update state
    result.current[1]({ activities: [{ id: 'test', name: 'Test', category: 'TestCategory' }] as any });

    expect(result.current[0].activities).toHaveLength(1);
  });
});

